import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";
import ts from "@chase-sets/typescript-compiler-api";
import {
  contextManifestContributesToApiHost,
  listBoundedContextManifests,
  listWorkspacePackages,
  normalizePath,
  repoRoot,
} from "./lib/repo.mjs";

const generatedRegistryComment = "// Generated by scripts/sync-workspace-metadata.mjs. Do not edit by hand.\n";
const generatedSchemaComment =
  "// Generated by scripts/sync-workspace-metadata.mjs from schema.sql. Do not edit by hand.\n";
const tsconfigBaseComment =
  "// Workspace tsconfigs extend this file or tsconfig.vitest.json; root tsconfig.json is only the editor/solution entry.\n";
const legacyTsconfigCompilerOptions = [
  "baseUrl",
  "charset",
  "importsNotUsedAsValues",
  "keyofStringsOnly",
  "noImplicitUseStrict",
  "noStrictGenericChecks",
  "out",
  "preserveValueImports",
  "suppressExcessPropertyErrors",
  "suppressImplicitAnyIndexErrors",
];
const ts7CompatibleCompilerOptions = {
  target: "ES2022",
  module: "Preserve",
  moduleResolution: "Bundler",
  lib: ["ES2022", "DOM", "DOM.Iterable"],
  jsx: "react-jsx",
  strict: true,
  skipLibCheck: true,
  esModuleInterop: true,
  forceConsistentCasingInFileNames: true,
  resolveJsonModule: true,
  allowSyntheticDefaultImports: true,
  noEmit: true,
};
const appBuildSemanticCompilerOptions = ["verbatimModuleSyntax"];

function buildLegacyPlatformRuntimeRegistryPaths(rootDir) {
  return [
    path.join(rootDir, "infrastructure", "platform-runtime", "api-context-registry.generated.ts"),
    path.join(rootDir, "infrastructure", "platform-runtime", "web-context-registry.generated.ts"),
  ];
}

function buildGeneratedRegistryOutputs(rootDir) {
  return [
    {
      kind: "api",
      hostName: "platform-api",
      outputPath: path.join(rootDir, "deployables", "platform-api", "src", "generated", "api-context-registry.ts"),
    },
    {
      kind: "worker",
      hostName: "platform-worker",
      outputPath: path.join(
        rootDir,
        "deployables",
        "platform-worker",
        "src",
        "generated",
        "worker-context-registry.ts",
      ),
    },
    {
      kind: "web",
      hostName: "admin-web",
      outputPath: path.join(rootDir, "deployables", "admin-web", "app", "generated", "web-context-registry.ts"),
    },
    {
      kind: "web",
      hostName: "marketplace-web",
      outputPath: path.join(rootDir, "deployables", "marketplace", "app", "generated", "web-context-registry.ts"),
    },
    {
      kind: "web",
      hostName: "public-web",
      outputPath: path.join(rootDir, "deployables", "public-web", "app", "generated", "web-context-registry.ts"),
    },
  ];
}

function sortObjectKeys(value) {
  return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)));
}

function normalizeRelative(filePath, rootDir) {
  return `./${normalizePath(path.relative(rootDir, filePath))}`;
}

function normalizeImportPath(fromFile, toFile) {
  const relativePath = normalizePath(path.relative(path.dirname(fromFile), toFile));
  return relativePath.startsWith(".") ? relativePath : `./${relativePath}`;
}

function toExportsObject(exportsField) {
  if (typeof exportsField === "string") {
    return { ".": exportsField };
  }

  return exportsField ?? {};
}

function buildTsconfigPaths(workspaces, rootDir) {
  const aliases = {};

  for (const workspace of workspaces) {
    const exportsField = toExportsObject(workspace.packageJson.exports);

    for (const [exportKey, exportTarget] of Object.entries(exportsField)) {
      if (typeof exportTarget !== "string") {
        continue;
      }

      const targetPath = normalizeRelative(path.join(workspace.dir, exportTarget.replace(/^\.\//, "")), rootDir);

      if (exportKey === ".") {
        aliases[workspace.name] = [targetPath];
        continue;
      }

      const exportSuffix = exportKey.replace(/^\.\//, "");
      aliases[`${workspace.name}/${exportSuffix}`] = [targetPath];
    }
  }

  return sortObjectKeys(aliases);
}

const localizationRoot = "contracts/localization/locales";
const englishLocaleRoot = `${localizationRoot}/en`;

function gitErrorMessage(error) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return String(error);
}

export function listTrackedLocaleModulePaths(rootDir, options = {}) {
  const execGit = options.execGit ?? execFileSync;
  let output;

  try {
    output = execGit("git", ["ls-files", "--", localizationRoot], {
      cwd: rootDir,
      encoding: "utf8",
    });
  } catch (error) {
    throw new Error(`Failed to discover tracked localization modules with git ls-files: ${gitErrorMessage(error)}`);
  }

  const trackedPaths = String(output)
    .trim()
    .split(/\r?\n/)
    .filter(Boolean)
    .map(normalizePath)
    .filter((filePath) => filePath.endsWith(".ts"))
    .sort((left, right) => left.localeCompare(right));

  if (trackedPaths.length === 0) {
    throw new Error(`Git discovery returned no tracked localization TypeScript modules under ${localizationRoot}.`);
  }

  return trackedPaths;
}

function unwrapExpression(expression) {
  let current = expression;

  while (
    ts.isAsExpression(current) ||
    ts.isParenthesizedExpression(current) ||
    ts.isSatisfiesExpression(current) ||
    ts.isTypeAssertionExpression(current)
  ) {
    current = current.expression;
  }

  return current;
}

function staticPropertyName(name) {
  if (ts.isIdentifier(name) || ts.isStringLiteral(name) || ts.isNumericLiteral(name)) {
    return name.text;
  }

  if (ts.isComputedPropertyName(name)) {
    const expression = unwrapExpression(name.expression);
    if (ts.isStringLiteral(expression) || ts.isNoSubstitutionTemplateLiteral(expression)) {
      return expression.text;
    }
  }

  return null;
}

function staticCatalogKeys(initializer) {
  const expression = unwrapExpression(initializer);
  if (!ts.isObjectLiteralExpression(expression) || expression.properties.length === 0) {
    return null;
  }

  const keys = [];
  for (const property of expression.properties) {
    if (!ts.isPropertyAssignment(property)) {
      return null;
    }

    const key = staticPropertyName(property.name);
    if (key === null) {
      return null;
    }
    keys.push(key);
  }

  return keys;
}

function hasExportModifier(node) {
  return ts.getModifiers(node)?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword) ?? false;
}

export function analyzeLocaleCatalogModule({ filePath, ownerLabel, source }) {
  const sourceFile = ts.createSourceFile(filePath, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const catalogDeclarations = new Map();
  const exportedNames = new Map();

  for (const statement of sourceFile.statements) {
    if (ts.isVariableStatement(statement)) {
      for (const declaration of statement.declarationList.declarations) {
        if (!ts.isIdentifier(declaration.name) || !declaration.initializer) {
          continue;
        }

        const keys = staticCatalogKeys(declaration.initializer);
        if (keys !== null) {
          catalogDeclarations.set(declaration.name.text, keys);
          if (hasExportModifier(statement)) {
            exportedNames.set(declaration.name.text, declaration.name.text);
          }
        }
      }
      continue;
    }

    if (ts.isExportDeclaration(statement) && !statement.moduleSpecifier && statement.exportClause) {
      if (!ts.isNamedExports(statement.exportClause)) {
        continue;
      }

      for (const element of statement.exportClause.elements) {
        exportedNames.set(element.propertyName?.text ?? element.name.text, element.name.text);
      }
    }
  }

  const candidates = [...catalogDeclarations.entries()]
    .filter(([localName]) => exportedNames.has(localName))
    .map(([localName, keys]) => ({
      exportName: exportedNames.get(localName),
      keys,
    }));

  if (candidates.length !== 1) {
    throw new Error(
      `Localization module "${filePath}" must export exactly one statically keyed catalog object; found ${candidates.length}.`,
    );
  }

  return {
    filePath,
    ownerLabel,
    exportName: candidates[0].exportName,
    keys: candidates[0].keys,
  };
}

export function assertNoLocaleCatalogKeyCollisions(modules) {
  const ownersByKey = new Map();

  for (const module of modules) {
    for (const key of module.keys) {
      const previous = ownersByKey.get(key);
      if (previous) {
        throw new Error(
          `Duplicate localization key "${key}" in "${previous.filePath}" (owner: ${previous.ownerLabel}) and "${module.filePath}" (owner: ${module.ownerLabel}).`,
        );
      }
      ownersByKey.set(key, module);
    }
  }
}

function localeOutputExportName(outputPath) {
  if (outputPath === `${englishLocaleRoot}.ts`) {
    return "englishTranslations";
  }

  const namespacePath = outputPath.slice(`${englishLocaleRoot}/`.length, -".ts".length);
  return `${toIdentifier(namespacePath)}EnglishTranslations`;
}

function buildLocaleCatalogOwnership(contexts, knownModulePaths) {
  const declarations = new Map();

  for (const context of contexts) {
    if (!Object.hasOwn(context.manifest, "localeCatalogs")) {
      continue;
    }

    if (
      !Array.isArray(context.manifest.localeCatalogs) ||
      context.manifest.localeCatalogs.some((entry) => typeof entry !== "string")
    ) {
      throw new Error(
        `Invalid localeCatalogs in ${normalizePath(context.manifestPath)}: expected an array of tracked module paths.`,
      );
    }

    for (const entry of context.manifest.localeCatalogs) {
      const modulePath = normalizePath(entry).replace(/^\.\//, "");
      if (!knownModulePaths.has(modulePath)) {
        throw new Error(
          `Invalid localeCatalogs entry "${entry}" in ${normalizePath(context.manifestPath)}: no tracked or generated locale module exists at that path.`,
        );
      }

      const previous = declarations.get(modulePath);
      if (previous) {
        throw new Error(
          `Locale catalog "${modulePath}" is declared by both ${previous.manifestPath} and ${normalizePath(context.manifestPath)}.`,
        );
      }

      declarations.set(modulePath, {
        contextName: context.contextName,
        manifestPath: normalizePath(context.manifestPath),
      });
    }
  }

  return declarations;
}

function localeModuleOwnerLabel(filePath, ownershipDeclarations) {
  let candidate = filePath;

  while (candidate.startsWith(`${englishLocaleRoot}/`)) {
    const owner = ownershipDeclarations.get(candidate);
    if (owner) {
      return `${owner.contextName} via ${owner.manifestPath}`;
    }

    const parentDirectory = normalizePath(path.posix.dirname(candidate));
    if (parentDirectory === englishLocaleRoot) {
      break;
    }
    candidate = `${parentDirectory}.ts`;
  }

  return filePath;
}

function buildLocaleMergeContent(outputPath, members, rootDir) {
  const outputAbsolutePath = path.resolve(rootDir, outputPath);
  const imports = members.map(
    (member) =>
      `import { ${member.exportName} } from "${normalizeImportPath(outputAbsolutePath, path.resolve(rootDir, member.filePath)).replace(/\.ts$/, "")}";`,
  );
  const spreads = members.map((member) => `  ...${member.exportName},`);
  const exportName = localeOutputExportName(outputPath);
  const keyType =
    outputPath === `${englishLocaleRoot}.ts`
      ? `\nexport type EnglishTranslationKey = keyof typeof ${exportName};\n`
      : "";

  return `${generatedRegistryComment}
${imports.join("\n")}

export const ${exportName} = {
${spreads.join("\n")}
} as const;
${keyType}`;
}

function buildLocaleCatalogPlan(contexts, trackedModulePaths, rootDir) {
  const englishTrackedPaths = trackedModulePaths.filter(
    (filePath) => filePath === `${englishLocaleRoot}.ts` || filePath.startsWith(`${englishLocaleRoot}/`),
  );
  const unsupportedPaths = trackedModulePaths.filter((filePath) => !englishTrackedPaths.includes(filePath));

  if (unsupportedPaths.length > 0) {
    throw new Error(
      `Tracked localization modules are outside the supported English tree: ${unsupportedPaths.join(", ")}.`,
    );
  }

  if (englishTrackedPaths.length === 0) {
    throw new Error(`Git discovery found no tracked English modules under ${englishLocaleRoot}.`);
  }

  const namespaceDirectories = new Set(
    englishTrackedPaths
      .filter((filePath) => filePath.startsWith(`${englishLocaleRoot}/`))
      .flatMap((filePath) => {
        const directories = [];
        let directory = normalizePath(path.posix.dirname(filePath));
        while (directory.startsWith(englishLocaleRoot)) {
          directories.push(directory);
          if (directory === englishLocaleRoot) {
            break;
          }
          directory = normalizePath(path.posix.dirname(directory));
        }
        return directories;
      }),
  );
  const outputPaths = [...namespaceDirectories]
    .map((directory) => `${directory}.ts`)
    .sort((left, right) => left.localeCompare(right));
  const outputPathSet = new Set(outputPaths);
  for (const outputPath of outputPaths.filter((candidate) => englishTrackedPaths.includes(candidate))) {
    const currentContent = readFileSync(path.join(rootDir, outputPath), "utf8");
    if (!currentContent.startsWith(generatedRegistryComment)) {
      throw new Error(
        `Tracked localization merge "${outputPath}" is not a generated artifact; refusing to overwrite it.`,
      );
    }
  }
  const leafPaths = englishTrackedPaths.filter((filePath) => !outputPathSet.has(filePath));
  const knownModulePaths = new Set([...trackedModulePaths, ...outputPaths]);
  const ownershipDeclarations = buildLocaleCatalogOwnership(contexts, knownModulePaths);
  const leafModules = leafPaths.map((filePath) => {
    let source;
    try {
      source = readFileSync(path.join(rootDir, filePath), "utf8");
    } catch (error) {
      throw new Error(`Failed to read tracked localization module "${filePath}": ${gitErrorMessage(error)}`);
    }

    return analyzeLocaleCatalogModule({
      filePath,
      ownerLabel: localeModuleOwnerLabel(filePath, ownershipDeclarations),
      source,
    });
  });

  assertNoLocaleCatalogKeyCollisions(leafModules);

  const outputs = outputPaths.map((outputPath) => {
    const namespaceDirectory = outputPath.slice(0, -".ts".length);
    const members = [
      ...leafModules.filter((module) => path.posix.dirname(module.filePath) === namespaceDirectory),
      ...outputPaths
        .filter(
          (candidate) =>
            candidate !== outputPath &&
            path.posix.dirname(candidate) === namespaceDirectory &&
            candidate.slice(0, -".ts".length).startsWith(`${namespaceDirectory}/`),
        )
        .map((candidate) => ({
          exportName: localeOutputExportName(candidate),
          filePath: candidate,
        })),
    ].sort((left, right) => left.filePath.localeCompare(right.filePath));

    if (members.length === 0) {
      throw new Error(`Generated localization merge "${outputPath}" has no discovered members.`);
    }

    return {
      outputPath,
      content: buildLocaleMergeContent(outputPath, members, rootDir),
    };
  });

  return {
    leafModules,
    outputs,
    stats: {
      scanned: leafModules.length,
      total: trackedModulePaths.length,
      generated: outputs.length,
      explicitlyExcluded: 0,
    },
  };
}

function toIdentifier(value) {
  const normalized = String(value)
    .replace(/[^A-Za-z0-9_$]+(.)?/g, (_match, next) => (next ? next.toUpperCase() : ""))
    .replace(/^[^A-Za-z_$]+/, "");

  return normalized.length > 0 ? normalized : "context";
}

function buildApiRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter((context) => contextManifestContributesToApiHost(context.manifest, hostName));
  const contextImports = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `import { contextManifest as ${identifier}Manifest, module as ${identifier}Module } from "${context.packageName}";`;
  });
  const entries = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${identifier}Manifest,
    module: ${identifier}Module,
  },`;
  });

  return `${generatedRegistryComment}
${contextImports.join("\n")}

export const apiContextRegistry = [
${entries.join("\n")}
] as const;
`;
}

function buildWorkerRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter(
    (context) =>
      context.manifest.runtimeDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeProfiles?.length > 0,
  );
  const contextImports = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `import { contextManifest as ${identifier}Manifest, module as ${identifier}Module } from "${context.packageName}";`;
  });
  const entries = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${identifier}Manifest,
    module: ${identifier}Module,
  },`;
  });

  return `${generatedRegistryComment}
${contextImports.join("\n")}

export const workerContextRegistry = [
${entries.join("\n")}
] as const;
`;
}

function contributesToWebHost(context, hostName) {
  return (
    context.manifest.deployableContributions?.some((contribution) => contribution.deployable === hostName) ||
    context.manifest.shellContributions?.some((contribution) => contribution.deployable === hostName)
  );
}

function buildWebRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter((context) => contributesToWebHost(context, hostName));
  const manifestImports = activeContexts.map(
    (context) => `import ${toIdentifier(context.contextName)}Manifest from "${context.packageName}/context";`,
  );
  const entries = activeContexts.map(
    (context) => `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${toIdentifier(context.contextName)}Manifest as WebContextRegistry[number]["manifest"],
  },`,
  );

  return `${generatedRegistryComment}
import type { WebContextRegistry } from "@chase-sets/platform-runtime/web";

${manifestImports.join("\n")}

export const webContextRegistry = [
${entries.join("\n")}
] as const satisfies WebContextRegistry;
`;
}

function writeFileEnsured(filePath, content) {
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, content, "utf8");
}

function checkExpectedFile(filePath, expectedContent, drift, rootDir) {
  if (!existsSync(filePath)) {
    drift.push(`${normalizePath(path.relative(rootDir, filePath))} is missing`);
    return;
  }

  const currentContent = readFileSync(filePath, "utf8");
  if (currentContent !== expectedContent) {
    drift.push(`${normalizePath(path.relative(rootDir, filePath))} is stale`);
  }
}

function readJsonc(filePath) {
  const content = readFileSync(filePath, "utf8");
  const parsed = ts.parseConfigFileTextToJson(filePath, content);
  if (parsed.error) {
    throw new Error(ts.flattenDiagnosticMessageText(parsed.error.messageText, "\n"));
  }

  return parsed.config;
}

function syncTsconfigBase(workspaces, options) {
  const { check, drift, rootDir } = options;
  const tsconfigBasePath = path.join(rootDir, "tsconfig.base.json");
  const current = readJsonc(tsconfigBasePath);
  current.compilerOptions = {
    ...current.compilerOptions,
    ...ts7CompatibleCompilerOptions,
  };
  for (const option of legacyTsconfigCompilerOptions) {
    delete current.compilerOptions[option];
  }
  for (const option of appBuildSemanticCompilerOptions) {
    delete current.compilerOptions[option];
  }
  current.compilerOptions.paths = buildTsconfigPaths(workspaces, rootDir);
  const content = `${tsconfigBaseComment}${JSON.stringify(current, null, 2)}\n`;

  if (check) {
    checkExpectedFile(tsconfigBasePath, content, drift, rootDir);
    return;
  }

  writeFileSync(tsconfigBasePath, content, "utf8");
}

function syncDeployableRegistries(workspaces, options) {
  const { check, drift, rootDir } = options;
  const contexts = listBoundedContextManifests({ repoRoot: rootDir, workspaces });

  for (const output of buildGeneratedRegistryOutputs(rootDir)) {
    const content =
      output.kind === "api"
        ? buildApiRegistry(output.outputPath, output.hostName, contexts)
        : output.kind === "worker"
          ? buildWorkerRegistry(output.outputPath, output.hostName, contexts)
          : buildWebRegistry(output.outputPath, output.hostName, contexts);

    if (check) {
      checkExpectedFile(output.outputPath, content, drift, rootDir);
    } else {
      writeFileEnsured(output.outputPath, content);
    }
  }

  for (const legacyPath of buildLegacyPlatformRuntimeRegistryPaths(rootDir)) {
    if (existsSync(legacyPath)) {
      if (check) {
        drift.push(`${normalizePath(path.relative(rootDir, legacyPath))} should be deleted`);
      } else {
        rmSync(legacyPath);
      }
    }
  }
}

function syncLocaleCatalogs(workspaces, options) {
  const { check, drift, rootDir } = options;
  const trackedModulePaths =
    options.trackedLocaleFiles ?? listTrackedLocaleModulePaths(rootDir, { execGit: options.execGit });
  const contexts = listBoundedContextManifests({ repoRoot: rootDir, workspaces });
  const plan = buildLocaleCatalogPlan(contexts, trackedModulePaths, rootDir);

  for (const output of plan.outputs) {
    const outputPath = path.join(rootDir, output.outputPath);
    if (check) {
      checkExpectedFile(outputPath, output.content, drift, rootDir);
    } else {
      writeFileEnsured(outputPath, output.content);
    }
  }

  return plan.stats;
}

function buildEventCorePostgresSchemaContent(schemaSql) {
  return `${generatedSchemaComment}export const eventCorePostgresSchemaSql =\n  ${JSON.stringify(
    normalizeLineEndings(schemaSql),
  )};\n`;
}

function normalizeLineEndings(value) {
  return value.replace(/\r\n/g, "\n");
}

function syncEventCorePostgresSchema(options) {
  const { check, drift, rootDir } = options;
  const schemaSqlPath = path.join(rootDir, "infrastructure", "event-core-postgres", "schema.sql");
  const schemaTsPath = path.join(rootDir, "infrastructure", "event-core-postgres", "schema.ts");
  const schemaSqlExists = existsSync(schemaSqlPath);
  const schemaTsExists = existsSync(schemaTsPath);

  if (!schemaSqlExists && !schemaTsExists) {
    return;
  }

  if (!schemaSqlExists) {
    drift.push(`${normalizePath(path.relative(rootDir, schemaSqlPath))} is missing`);
    return;
  }

  const content = buildEventCorePostgresSchemaContent(readFileSync(schemaSqlPath, "utf8"));

  if (check) {
    checkExpectedFile(schemaTsPath, content, drift, rootDir);
    return;
  }

  writeFileEnsured(schemaTsPath, content);
}

export function syncWorkspaceMetadata(options = {}) {
  const check = options.check ?? false;
  const rootDir = options.rootDir ?? repoRoot;
  const workspaces = options.workspaces ?? listWorkspacePackages({ repoRoot: rootDir });
  const drift = [];

  const localeCatalogs = syncLocaleCatalogs(workspaces, {
    check,
    drift,
    rootDir,
    trackedLocaleFiles: options.trackedLocaleFiles,
    execGit: options.execGit,
  });
  syncTsconfigBase(workspaces, { check, drift, rootDir });
  syncDeployableRegistries(workspaces, { check, drift, rootDir });
  syncEventCorePostgresSchema({ check, drift, rootDir });

  if (drift.length > 0) {
    throw new Error(
      [
        "Workspace metadata is out of date:",
        ...drift.map((entry) => `- ${entry}`),
        "Run pnpm run sync:workspace-metadata to refresh generated workspace metadata.",
      ].join("\n"),
    );
  }

  return { checked: check, drift, localeCatalogs };
}

function parseArgs(args) {
  if (args.length === 0) {
    return { check: false };
  }

  if (args.length === 1 && args[0] === "--check") {
    return { check: true };
  }

  throw new Error("Usage: node ./scripts/sync-workspace-metadata.mjs [--check]");
}

function main() {
  const options = parseArgs(process.argv.slice(2));
  const result = syncWorkspaceMetadata(options);
  console.log(
    `Localization catalog discovery: scanned=${result.localeCatalogs.scanned}/${result.localeCatalogs.total}; generated=${result.localeCatalogs.generated}; explicitly-excluded=${result.localeCatalogs.explicitlyExcluded}.`,
  );
  console.log(result.checked ? "Workspace metadata is current." : "Workspace metadata synchronized.");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
